dialog{max-height:calc(100dvh - 40px - env(safe-area-inset-top));overscroll-behavior:contain}#status{font-size:13px;position:relative;z-index:2;color:#7b3458;background:#fff0f6;padding:0 16px}#status:not(:empty){padding:10px 16px;border-bottom:1px solid #f1d4e0}.detail{grid-template-columns:95px minmax(0,1fr)}
@media(max-width:400px){.item.row{gap:7px}.item.row>.grow{flex-basis:calc(100% - 65px)}.item.row>.btn{flex:1}.card{padding:14px}.footer .btn{font-size:13px}}
